const http = require('http');
const fs = require('fs');
const path = require('path');

const endpoint = 'http://127.0.0.1:63685/status';

http.get(endpoint, (res) => {
  let body = '';
  res.on('data', (chunk) => { body += chunk; });
  res.on('end', () => {
    const data = JSON.parse(body);
    const outDir = path.join(__dirname, 'results');
    fs.mkdirSync(outDir, { recursive: true });
    fs.writeFileSync(path.join(outDir, 'status.json'), JSON.stringify({ status: data.status }));
    console.log('written status=' + data.status);
  });
}).on('error', (err) => {
  console.error(err);
  process.exit(1);
});

